BEGIN TRY
  BEGIN TRANSACTION;
  UPDATE WorkOrders SET MaintainerId = @MaintainerId WHERE Id = @WorkOrderId;
  UPDATE InspectionReports SET MaintainerId = @MaintainerId WHERE WorkOrderId = @WorkOrderId;
  COMMIT;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT > 0 ROLLBACK;
  THROW;
END CATCH;

BEGIN TRANSACTION;
IF EXISTS (
  SELECT 1 FROM @PlantCodes p
  WHERE NOT EXISTS (SELECT 1 FROM Plants x WHERE x.Code = p.Code)
)
BEGIN
  ROLLBACK;
  THROW 50000, 'Uno o più PlantCode non esistono', 1;
END;
UPDATE p SET MaintainerId = @MaintainerId
FROM Plants p JOIN @PlantCodes x ON x.Code = p.Code;
COMMIT;

if (!e.value) {
  this.documentItem.removeArticle();
  return;
}
this.articlesService.details(e.value)
  .subscribe(article => this.documentItem.assignArticle(article));

this.form.valueChanges
  .pipe(takeUntilDestroyed(this.destroyRef))
  .subscribe(value => this.save(value));

this.items = [];
if (!this.customerId) return;
this.service.dropdown(this.customerId).subscribe(data => this.items = data.Items);

var count = 0;
foreach (var code in codes) {
  if (string.IsNullOrWhiteSpace(code)) continue;
  if (!code.StartsWith("RA-", StringComparison.OrdinalIgnoreCase)) continue;
  count++;
}
return count;

